"""
LiftPlan AI Dashboard — Stage 5.

A Streamlit app that runs the full pipeline (triage-adjacent extraction,
classification, traffic study, specification recommendation, and
contradiction detection) on an uploaded drawing (and optional
specification document) and presents the results per group, with a
compliance checklist and contradiction flags.

This file is deliberately thin — all the actual logic lives in
pipeline.py (and the modules it calls), which are unit tested
independently. This file's only job is to render what pipeline.py
returns.

Run with:
    streamlit run app.py
"""

import sys
import tempfile
from pathlib import Path

import streamlit as st

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))

from src.dashboard.pipeline import run_pipeline


st.set_page_config(page_title="LiftPlan AI", page_icon="\U0001F6D7", layout="wide")

# The cabin photo is embedded as base64 so the app stays a single file with
# no extra static-asset wiring (Streamlit's static file serving is opt-in
# and adds config the rest of the project doesn't otherwise need).
_CABIN_PHOTO_B64 = ""


def card(body_html: str, tone: str = "default") -> None:
    """Render one boxed note. Every result/notice on this page goes through
    here instead of st.info/warning/success/error — those colours come from
    Streamlit's internal theme, which we don't have reliable control over
    across versions. This gives every box the same light, neutral look,
    with red reserved for the one thing genuinely worth flagging red:
    a real compliance problem or a hard error.
    """
    cls = "lp-card lp-card-error" if tone == "error" else "lp-card"
    st.markdown(f'<div class="{cls}">{body_html}</div>', unsafe_allow_html=True)


def levels_table_html(rows) -> str:
    body = "".join(
        f'<tr><td>{r["label"]}</td>'
        f'<td class="lp-mono" style="text-align:right;">{r["elevation_mm"]}</td></tr>'
        for r in rows
    )
    return (
        '<table class="lp-table"><thead><tr><th>Level</th>'
        '<th style="text-align:right;">Elevation (mm)</th></tr></thead>'
        f'<tbody>{body}</tbody></table>'
    )


# Canonical field name (from real_lift_specification_extractor.py) -> a
# short, human-readable column header for the dashboard table. Only the
# fields most relevant to specifying a lift are shown here (a full
# per-field dump is available in the Raw pipeline output expander for
# anyone who wants every field the table happened to contain).
SPEC_FIELD_DISPLAY = [
    ("capacity", "Rated Load / Capacity"),
    ("speed", "Speed"),
    ("stops", "Stops / Landing Doors"),
    ("travel", "Travel"),
    ("elevator_type", "Type"),
    ("operation", "Operation"),
    ("power_per_lift", "Power per Lift"),
]


def elevator_specs_table_html(groups) -> str:
    header = "".join(f"<th>{label}</th>" for _, label in SPEC_FIELD_DISPLAY)
    rows_html = ""
    for g in groups:
        fields = g["fields"]
        cells = "".join(
            f"<td>{fields.get(key, '\u2014')}</td>" for key, _ in SPEC_FIELD_DISPLAY
        )
        rows_html += f'<tr><td class="lp-mono">{g["lift_ids"]}</td>{cells}</tr>'
    return (
        '<table class="lp-table"><thead><tr><th>Lift(s)</th>'
        f'{header}</tr></thead><tbody>{rows_html}</tbody></table>'
    )


